const rows = $('Traer Prospectos').all().flatMap(i => i.json).flat(1).filter(x => x && typeof x === 'object');
const DELTAS = [0, 2, 3, 4, 6, 15];
const now = Date.now();
const MENSAJES = {
  0: 'Hola {N} 👋 Soy Jean, de JeanCRG. Vi que {B} trabaja por WhatsApp y quiero mostrarle algo: un asistente con IA que responde solo, agenda citas y captura clientes las 24h. ¿Le interesa una demo de 5 minutos? Sin compromiso.',
  1: 'Hola {N} 👋 Le escribí hace unos días sobre el asistente IA para WhatsApp. ¿Sigue interesado en ver una demo de 5 minutos?',
  2: 'Hola {N} 😊 Solo quería retomar el tema del asistente IA. Tenemos un piloto de 15 días por $800.000 (100% descontable). ¿Le cuento cómo funciona?',
  3: 'Hola {N}, ¿qué tal? Le dejo el enlace para agendar una consulta gratis de 30 minutos: https://calendly.com/jeancrg/consulta-gratuita. Sin compromiso.',
  4: 'Hola {N} 🙌 Último mensaje por ahora. Si en algún momento quiere automatizar su WhatsApp, aquí estamos. ¡Éxitos con {B}!',
  5: 'Hola {N}, ¿cómo va {B}? Si quiere reactivar el tema del asistente IA, seguimos disponibles. ¡Un abrazo!'
};
const pendientes = [];
for (const p of rows) {
  const toque = p.toque || 0;
  if (toque >= 5) continue;
  const ult = p.fecha_ultimo_toque ? new Date(p.fecha_ultimo_toque).getTime() : null;
  const deltaDias = DELTAS[Math.min(toque, 5)];
  const due = ult === null || (now - ult) >= deltaDias * 86400000;
  if (!due) continue;
  const tel = String(p.telefono || '').replace(/\D/g, '');
  const msj = MENSAJES[Math.min(toque, 5)].replace('{N}', p.nombre || 'amigo').replace('{B}', p.negocio || 'su negocio');
  pendientes.push({ json: {
    nombre: p.nombre, negocio: p.negocio, telefono: tel, toque: toque + 1,
    wa: 'https://wa.me/' + tel,
    marcar: 'https://n8n-production-d5b6.up.railway.app/webhook/marcar-toque?secret=jeancrg2026panel&telefono=' + tel,
    mensaje: msj
  } });
}
return pendientes;
